<template><div class="training-page"><div class="page-heading"><div><div class="eyebrow">GYMMIND TRAINING</div><h2 class="simple-page-title">{{ profile.title }}</h2><p class="simple-page-desc">{{ profile.description }}</p></div><el-button v-if="isMember" type="primary" @click="showRecord=true">开始训练</el-button></div><div class="toolbar simple-card"><el-radio-group v-model="range" @change="load"><el-radio-button value="7">本周</el-radio-button><el-radio-button value="30">近 30 天</el-radio-button><el-radio-button value="90">近 90 天</el-radio-button></el-radio-group><el-input v-if="!isMember" v-model="memberId" placeholder="会员 ID（可选）" clearable style="width:180px" @keyup.enter="load"/><el-button @click="load">查询</el-button></div><div v-loading="loading" class="stats-grid"><div v-for="stat in stats" :key="stat.label" class="stat-card"><span>{{ stat.label }}</span><strong>{{ stat.value }}</strong></div></div><div v-if="!isMember" class="simple-card panel"><div class="heading"><h3>{{ isPlatform ? '门店训练概览' : '会员训练概览' }}</h3><span>{{ data.members.length }} 个对象</span></div><el-table :data="data.members" stripe><el-table-column prop="name" label="会员"/><el-table-column prop="workoutCount" label="训练次数"/><el-table-column prop="totalMinutes" label="训练时长（分钟）"/><el-table-column prop="lastWorkout" label="最近训练"/><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click="selectMember(scope.row.memberId)">查看</el-button></template></el-table-column></el-table><el-empty v-if="!data.members.length" description="暂无训练记录"/></div><div class="simple-card panel"><div class="heading"><h3>{{ isMember ? '我的训练记录' : '训练记录' }}</h3><span>{{ data.records.length }} 条</span></div><el-table :data="data.records" stripe><el-table-column prop="workoutDate" label="日期"/><el-table-column v-if="!isMember" prop="memberId" label="会员 ID"/><el-table-column prop="duration" label="时长（分钟）"/><el-table-column prop="calories" label="消耗热量"/><el-table-column prop="notes" label="备注"/></el-table><el-empty v-if="!data.records.length" description="暂无训练记录，开始今天的第一条训练"/></div><el-dialog v-model="showRecord" title="记录一次训练" width="520px"><el-form label-position="top"><el-form-item label="训练日期"><el-date-picker v-model="form.workoutDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="训练时长（分钟）"><el-input-number v-model="form.duration" :min="1"/></el-form-item><el-form-item label="动作 ID"><el-input-number v-model="form.exerciseId" :min="1"/></el-form-item><el-form-item label="备注"><el-input v-model="form.notes" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="showRecord=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveRecord">保存训练记录</el-button></template></el-dialog></div></template>
<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {ElMessage} from 'element-plus';import {useAuthStore} from '@/stores/auth';import {trainingApi,type TrainingOverview} from '@/api/training';import {workoutRecordsApi} from '@/api/workouts';
const auth=useAuthStore(),loading=ref(false),saving=ref(false),range=ref('30'),memberId=ref(''),selectedMember=ref<number>(),showRecord=ref(false);const data=ref<TrainingOverview>({role:'',since:'',until:'',summary:{workoutCount:0,activeMembers:0,totalMinutes:0,averageMinutes:0,streakDays:0},records:[],members:[]});const form=reactive({workoutDate:new Date().toISOString().slice(0,10),duration:45,exerciseId:1,notes:'完成今日训练'});const isMember=computed(()=>auth.roles.includes('MEMBER')&&!auth.roles.includes('COACH')&&!auth.roles.includes('GYM_ADMIN')&&!auth.isPlatformAdmin),isPlatform=computed(()=>auth.isPlatformAdmin),profile=computed(()=>isMember.value?{title:'我的训练',description:'记录每一次训练，持续看到自己的进步。'}:isPlatform.value?{title:'平台训练概览',description:'查看各门店训练活跃度和趋势。'}:{title:'训练管理',description:'查看会员训练进度，及时跟进低活跃会员。'}),stats=computed(()=>[{label:'训练次数',value:data.value.summary.workoutCount},{label:isMember.value?'训练人数':'训练人数',value:data.value.summary.activeMembers},{label:'总训练时长',value:data.value.summary.totalMinutes+' 分钟'},{label:'平均每次',value:Math.round(data.value.summary.averageMinutes)+' 分钟'},{label:'连续训练',value:data.value.summary.streakDays+' 天'}]);
async function load(){loading.value=true;try{const e=new Date(),s=new Date();s.setDate(e.getDate()-Number(range.value)+1);data.value=(await trainingApi.overview(s.toISOString().slice(0,10),e.toISOString().slice(0,10),selectedMember.value||Number(memberId.value)||undefined)).data}catch(e:any){ElMessage.error(e?.response?.data?.message||'训练数据加载失败')}finally{loading.value=false}}function selectMember(id:number){selectedMember.value=id;void load()}async function saveRecord(){saving.value=true;try{await workoutRecordsApi.create({workoutDate:form.workoutDate,duration:form.duration,calories:200,notes:form.notes,sets:[{exerciseId:form.exerciseId,setNumber:1,weight:0,reps:10,duration:0,completed:true}]});showRecord.value=false;ElMessage.success('训练记录已保存');await load()}catch(e:any){ElMessage.error(e?.response?.data?.message||'保存失败')}finally{saving.value=false}}onMounted(load)
</script><style scoped>.training-page{max-width:1100px;margin:auto}.page-heading,.toolbar,.heading{display:flex;align-items:center;justify-content:space-between;gap:14px}.eyebrow{color:var(--primary);font-size:11px;font-weight:700;letter-spacing:1.5px}.toolbar{margin:18px 0;padding:14px}.stats-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:16px}.stat-card,.panel{padding:18px}.stat-card{border:1px solid var(--border);border-radius:8px;background:#fff}.stat-card span{display:block;color:var(--text-muted);font-size:12px}.stat-card strong{display:block;color:var(--primary);font-size:24px;margin-top:8px}.panel{margin-bottom:16px}.heading{margin-bottom:14px}.heading h3{margin:0}@media(max-width:800px){.stats-grid{grid-template-columns:repeat(2,1fr)}.toolbar{flex-wrap:wrap}}</style>
